import 'package:flutter/material.dart';import '../core/utils/formatters.dart';import '../data/repositories/expense_repository.dart';
class ReportsScreen extends StatefulWidget{const ReportsScreen({super.key});@override State<ReportsScreen> createState()=>_ReportsScreenState();}
class _ReportsScreenState extends State<ReportsScreen>{final repo=ExpenseRepository();late Future<_Data> future;@override void initState(){super.initState();future=load();}Future<_Data> load()async{final n=DateTime.now();return _Data(await repo.totals(DateTime(n.year,n.month),DateTime(n.year,n.month+1)),await repo.transactions(type:'expense',from:DateTime(n.year,n.month)),await repo.categories(type:'expense'));}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Reports & insights')),body:FutureBuilder<_Data>(future:future,builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!,income=d.totals['income']!/100,expense=d.totals['expense']!/100,total=d.items.fold<int>(0,(v,e)=>v+e.amountMinor);final map=<int,int>{};for(final e in d.items){map[e.categoryId]=(map[e.categoryId]??0)+e.amountMinor;}final rows=map.entries.toList()..sort((a,b)=>b.value.compareTo(a.value));String name(int id)=>d.cats.where((e)=>e['id']==id).map((e)=>e['name'] as String).firstOrNull??'Other';return ListView(padding:const EdgeInsets.all(20),children:[Text(Fmt.month(DateTime.now()),style:const TextStyle(color:Colors.grey)),const SizedBox(height:14),_metric('Income',income,Colors.green),_metric('Expenses',expense,Colors.deepOrange),_metric('Net savings',income-expense,Colors.blue),const SizedBox(height:20),Text('Spending by category',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:12),if(rows.isEmpty)const Text('No expenses this month.')else ...rows.map((e){final ratio=total==0?0.0:e.value/total;return Padding(padding:const EdgeInsets.only(bottom:16),child:Column(children:[Row(children:[Expanded(child:Text(name(e.key))),Text(Fmt.money(e.value/100)+'  '+(ratio*100).round().toString()+'%')]),const SizedBox(height:7),LinearProgressIndicator(value:ratio,minHeight:8)]));})]);}));}
 Widget _metric(String label,double value,Color color)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:const TextStyle(color:Colors.grey)),const SizedBox(height:5),Text(Fmt.money(value),style:TextStyle(fontSize:22,fontWeight:FontWeight.w800,color:color))])));
}
class _Data{_Data(this.totals,this.items,this.cats);final Map<String,int> totals;final List items;final List<Map<String,Object?>> cats;}
